<?php require 'config.php';auth();$s=$db->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$s->execute([$_SESSION['id']]);head('My orders');?><h1>My orders</h1><?php foreach($s as $o):?><article class="card"><h3>Order #<?=h($o['id'])?></h3><p><?=h($o['created_at'])?> • <?=h($o['status'])?></p><strong>ETB <?=h($o['total'])?></strong><?php $i=$db->prepare('SELECT p.name,oi.quantity,oi.price FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?');$i->execute([$o['id']]);foreach($i as $item):?><p><?=h($item['name'])?> × <?=h($item['quantity'])?> — ETB <?=h($item['price'])?></p><?php endforeach;?></article><?php endforeach;foot();?>
